('4', '0', '2026-07-06 20:58:24', '2026-07-06 20:58:24', '<!-- wp:page-list /-->', 'Navigatie', '', 'publish', 'closed', 'closed', '', 'navigation', '', '', '2026-07-06 20:58:24', '2026-07-06 20:58:24', '', '0', 'http://localhost/warmvast/C:/Program%20Files/Git/navigation/', '0', 'wp_navigation', '', '0'),
('5', '0', '2026-07-06 21:17:52', '2026-07-06 21:17:52', '', 'Home', '', 'publish', 'closed', 'closed', '', 'home', '', '', '2026-07-06 21:17:52', '2026-07-06 21:17:52', '', '0', 'http://localhost/warmvast/home/', '0', 'page', '', '0'),
('6', '0', '2026-07-06 21:17:53', '2026-07-06 21:17:53', '', 'Isolatie', 'Spouw, vloer, glas of dak isoleren? Warmvast kijkt naar uw woning als systeem en berekent per maatregel de ISDE-subsidie en besparing.', 'publish', 'closed', 'closed', '', 'isolatie', '', '', '2026-07-12 12:34:05', '2026-07-12 12:34:05', '', '0', 'http://localhost/warmvast/isolatie/', '0', 'page', '', '0'),
('7', '0', '2026-07-06 21:17:54', '2026-07-06 21:17:54', '', 'Spouwmuurisolatie', 'Lege of slecht gevulde spouw? Spouwmuurisolatie is snel uitgevoerd, kosteneffectief en levert direct meer wooncomfort op. Bereken uw ISDE-subsidie.', 'publish', 'closed', 'closed', '', 'spouwmuurisolatie', '', '', '2026-07-12 12:34:05', '2026-07-12 12:34:05', '', '0', 'http://localhost/warmvast/spouwmuurisolatie/', '0', 'page', '', '0'),
('8', '0', '2026-07-06 21:17:56', '2026-07-06 21:17:56', '', 'Vloerisolatie', 'Koude vloer en tocht uit de kruipruimte? Vloerisolatie houdt de warmte binnen en de kou onder de vloer. Bereken uw ISDE-subsidie voor vloerisolatie.', 'publish', 'closed', 'closed', '', 'vloerisolatie', '', '', '2026-07-12 12:34:05', '2026-07-12 12:34:05', '', '0', 'http://localhost/warmvast/vloerisolatie/', '0', 'page', '', '0'),
('9', '0', '2026-07-06 21:17:58', '2026-07-06 21:17:58', '', 'Glasisolatie HR++', 'Enkel of oud dubbel glas isoleert slecht. HR++ glas beperkt warmteverlies sterk en verhoogt direct het wooncomfort. Bereken uw ISDE-subsidie.', 'publish', 'closed', 'closed', '', 'glasisolatie-hr', '', '', '2026-07-12 12:34:05', '2026-07-12 12:34:05', '', '0', 'http://localhost/warmvast/glasisolatie-hr/', '0', 'page', '', '0'),
('10', '0', '2026-07-06 21:17:59', '2026-07-06 21:17:59', '', 'Dakisolatie', 'Een ongeïsoleerd dak of zolder veroorzaakt het grootste warmteverlies in huis. Dakisolatie pakt dit structureel aan. Bereken uw ISDE-subsidie.', 'publish', 'closed', 'closed', '', 'dakisolatie', '', '', '2026-07-12 12:34:05', '2026-07-12 12:34:05', '', '0', 'http://localhost/warmvast/dakisolatie/', '0', 'page', '', '0'),
('11', '0', '2026-07-06 21:18:01', '2026-07-06 21:18:01', '', 'Subsidie service', 'ISDE-subsidie voor isolatie: vast bedrag per m², verdubbeling bij twee maatregelen. Warmvast regelt opname, uitvoering en het subsidiedossier.', 'publish', 'closed', 'closed', '', 'subsidie-service', '', '', '2026-07-12 12:34:05', '2026-07-12 12:34:05', '', '0', 'http://localhost/warmvast/subsidie-service/', '0', 'page', '', '0'),
